import{_ as t,o as r,c as n,a2 as i}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Wie lasse ich Geräte automatisch finden und wie steuere ich, welche gelistet werden?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/02.anleitungen/01.geraete-entdecken.md"},"headers":[],"relativePath":"de/adapter/esphome/anleitungen/geraete-entdecken.md","filePath":"de/adapter/esphome/anleitungen/geraete-entdecken.md","lastUpdated":1795571670000}'),a={name:"de/adapter/esphome/anleitungen/geraete-entdecken.md"};function d(s,e,o,h,u,c){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="wie-lasse-ich-gerate-automatisch-finden-und-wie-steuere-ich-welche-gelistet-werden" tabindex="-1">Wie lasse ich Geräte automatisch finden und wie steuere ich, welche gelistet werden? <a class="header-anchor" href="#wie-lasse-ich-gerate-automatisch-finden-und-wie-steuere-ich-welche-gelistet-werden" aria-label="Permalink to &quot;Wie lasse ich Geräte automatisch finden und wie steuere ich, welche gelistet werden?&quot;">​</a></h1><p><a id="auto-discovery-report-routers-foreign"></a></p><h2 id="warum-meldet-die-auto-discovery-router-oder-fremde-gerate-als-esphome-und-wie-schließe-ich-eine-ip-aus" tabindex="-1">Warum meldet die Auto-Discovery Router oder fremde Geräte als ESPHome und wie schließe ich eine IP aus? <a class="header-anchor" href="#warum-meldet-die-auto-discovery-router-oder-fremde-gerate-als-esphome-und-wie-schließe-ich-eine-ip-aus" aria-label="Permalink to &quot;Warum meldet die Auto-Discovery Router oder fremde Geräte als ESPHome und wie schließe ich eine IP aus?&quot;">​</a></h2><p>Die Erkennung meldet alles, was im Netz auf die Suche nach ESPHome-Geräten antwortet. Manche Router und andere Geräte antworten ebenfalls und erscheinen dann im Reiter „Geräte“ in der Gruppe „Gefunden, noch nicht hinzugefügt“. Der Adapter verbindet sich mit gefundenen Geräten nie von selbst, sie bleiben dort, bis du sie hinzufügst.</p><p>So schließt du eine Adresse aus:</p><ol><li>Öffne die Einstellungen der Instanz, Reiter „Haupteinstellungen“, Bereich „Erkennung“.</li><li>Trag die Adresse in die Tabelle „IP-Adressen, die von der Geräteerkennung ausgeschlossen werden sollen“ ein. Name und Beschreibung sind nur für dich.</li><li>Speichere. Die Instanz startet neu und überspringt die Adresse ab jetzt.</li></ol><p>Die Adresse muss genau so geschrieben sein, wie das Gerät sie meldet. Die Liste wirkt nur auf die Erkennung, ein schon hinzugefügtes Gerät verbindet sich weiter. Brauchst du die Erkennung gar nicht, schalte „Geräteerkennung aktiviert“ aus und füg Geräte von Hand hinzu.</p><p><a id="choose-network-interface-device-discovery"></a></p><h2 id="kann-ich-die-netzwerkschnittstelle-fur-die-gerate-erkennung-wahlen" tabindex="-1">Kann ich die Netzwerkschnittstelle für die Geräte-Erkennung wählen? <a class="header-anchor" href="#kann-ich-die-netzwerkschnittstelle-fur-die-gerate-erkennung-wahlen" aria-label="Permalink to &quot;Kann ich die Netzwerkschnittstelle für die Geräte-Erkennung wählen?&quot;">​</a></h2><p>Ja. Im Reiter „Haupteinstellungen“, Bereich „Erkennung“, legt „Anhörungsadresse“ fest, auf welcher Schnittstelle der Adapter nach Geräten sucht. Das Feld erscheint, wenn „Geräteerkennung aktiviert“ an ist.</p><table tabindex="0"><thead><tr><th>Eintrag</th><th>Wirkung</th></tr></thead><tbody><tr><td>leer oder <code>0.0.0.0</code></td><td>sucht auf allen IPv4-Schnittstellen (Standard)</td></tr><tr><td>IPv4-Adresse des ioBroker-Rechners</td><td>sucht nur auf dieser Schnittstelle</td></tr><tr><td>IPv6-Adresse des ioBroker-Rechners</td><td>sucht per IPv6 auf dieser Schnittstelle</td></tr></tbody></table><p>Gehört die Adresse zu keiner Schnittstelle, steht eine Warnung im Log, und der Adapter sucht auf allen IPv4-Schnittstellen. Die Einstellung gilt nur für die Erkennung. Mit hinzugefügten Geräten verbindet sich der Adapter immer über deren Adresse.</p><p><a id="devices-another-vlan-iobroker-runs"></a></p><h2 id="wie-finde-ich-gerate-in-einem-anderen-vlan-oder-wenn-iobroker-in-docker-lauft" tabindex="-1">Wie finde ich Geräte in einem anderen VLAN oder wenn ioBroker in Docker läuft? <a class="header-anchor" href="#wie-finde-ich-gerate-in-einem-anderen-vlan-oder-wenn-iobroker-in-docker-lauft" aria-label="Permalink to &quot;Wie finde ich Geräte in einem anderen VLAN oder wenn ioBroker in Docker läuft?&quot;">​</a></h2><p>Die Erkennung nutzt mDNS, und mDNS erreicht nur das eigene Netz. Geräte in einem anderen VLAN oder hinter einem Docker-Netz findet sie deshalb nicht. Füg solche Geräte von Hand mit IP-Adresse oder Hostnamen hinzu, die Verbindung selbst geht über Netzgrenzen hinweg.</p><p>Dafür muss der ioBroker-Rechner das Gerät auf TCP-Port 6053 erreichen, dem Port der ESPHome-API. Lass ihn in der Firewall zwischen den Netzen zu.</p><p>Läuft ioBroker in Docker, sieht der Container mDNS nur mit Host-Netzwerk. Ohne Host-Netzwerk fügst du die Geräte von Hand hinzu.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erstes-geraet#add-esphome-device-adapter">Gerät hinzufügen</a> · <a href="./../hintergrund/adapter-und-dashboard#adapter-dashboard-show-device-status">Gerätestatus im Dashboard</a></p><p><a id="adapter-support-iobroker-discovery"></a></p><h2 id="unterstutzt-der-adapter-iobroker-discovery" tabindex="-1">Unterstützt der Adapter ioBroker.discovery? <a class="header-anchor" href="#unterstutzt-der-adapter-iobroker-discovery" aria-label="Permalink to &quot;Unterstützt der Adapter ioBroker.discovery?&quot;">​</a></h2><p>Ja. ioBroker.discovery findet ESPHome-Geräte im Netz und schlägt vor, eine Instanz dieses Adapters anzulegen.</p><p>Die Geräte selbst findet der Adapter mit seiner eigenen Erkennung, dafür braucht er ioBroker.discovery nicht. Sie läuft, solange „Geräteerkennung aktiviert“ an ist, und zeigt gefundene Geräte im Reiter „Geräte“.</p><p><strong>Siehe auch:</strong> <a href="#auto-discovery-report-routers-foreign">Was die Erkennung meldet</a></p>',23)])])}const p=t(a,[["render",d]]);export{g as __pageData,p as default};
